            --border-color: #e0e0e0;
            --text-gray: #666666;
        }
        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }
        body {
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
            color: var(--primary-color);
            background-color: var(--bg-color);
            line-height: 1.6;
        }
        a {
            text-decoration: none;
            color: inherit;
        }
        ul {
            list-style: none;
        }
        /* Header */
        header {
            background: var(--white);
            border-bottom: 1px solid var(--border-color);
            padding: 20px 40px;
            display: flex;
            justify-content: space-between;
            align-items: center;
            position: sticky;
            top: 0;
            z-index: 100;
        }
        .logo {
            font-size: 24px;
            font-weight: bold;
            letter-spacing: 2px;
        }
        nav ul {
            display: flex;
            gap: 30px;
        }
        nav a {
            font-size: 16px;
            transition: color 0.3s;
        }
        nav a:hover {
            color: var(--accent-color);
        }
        .cart-icon {
            position: relative;
            cursor: pointer;
        }
        .cart-count {
            position: absolute;
            top: -8px;
            right: -8px;
            background: var(--accent-color);
            color: var(--white);
            font-size: 12px;
            width: 18px;
            height: 18px;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
        }
        /* Hero */
        .hero {
            background-color: #e8e4de;
            padding: 100px 40px;
            text-align: center;
        }
        .hero h1 {
            font-size: 48px;
            margin-bottom: 20px;
            font-weight: 400;
        }
        .hero p {
            font-size: 18px;
            color: var(--text-gray);
            margin-bottom: 30px;
            max-width: 600px;
            margin-left: auto;
            margin-right: auto;
        }
        .btn {
            display: inline-block;
            padding: 12px 30px;
            background: var(--primary-color);
            color: var(--white);
            border-radius: 2px;
            font-size: 14px;
            transition: background 0.3s;
        }
        .btn:hover {
            background: var(--accent-color);
        }
        /* Categories */
        .categories {
            padding: 60px 40px;
            max-width: 1200px;
            margin: 0 auto;
        }
        .section-title {
            text-align: center;
            font-size: 28px;
            margin-bottom: 40px;
            font-weight: 400;
        }
        .category-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
            gap: 20px;
        }
        .category-card {
            background: var(--white);
            padding: 40px 20px;
            text-align: center;
            border: 1px solid var(--border-color);
            cursor: pointer;
            transition: transform 0.3s;
        }
        .category-card:hover {
            transform: translateY(-5px);
            border-color: var(--accent-color);
        }
        .category-card h3 {
            font-size: 20px;
            margin-bottom: 10px;
        }
        /* Featured Products */
        .featured {
            background: var(--white);
            padding: 60px 40px;
        }
        .product-grid {
            display: grid;
            grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
            gap: 30px;
            max-width: 1200px;
            margin: 0 auto;
        }
        .product-card {
            cursor: pointer;
        }
        .product-image {
            width: 100%;
            height: 350px;
            background-color: #e0e0e0;
            display: flex;
            align-items: center;
            justify-content: center;
            color: #999;
            margin-bottom: 15px;
            position: relative;
            overflow: hidden;
        }
        .product-info {
            text-align: center;
        }
        .product-name {
            font-size: 16px;
            margin-bottom: 5px;
        }
        .product-price {
            color: var(--accent-color);
            font-weight: bold;
        }
        .old-price {
            text-decoration: line-through;
            color: #999;
            font-size: 14px;
            margin-left: 5px;
        }
        /* Footer */
        footer {
            background: var(--primary-color);
            color: #ccc;
            padding: 60px 40px;
            margin-top: 40px;
        }
        .footer-content {
            max-width: 1200px;
            margin: 0 auto;
            display: flex;
            justify-content: space-between;
            flex-wrap: wrap;
            gap: 30px;
        }
        .footer-column h4 {
            color: var(--white);
            margin-bottom: 20px;
        }
        .footer-column ul li {
            margin-bottom: 10px;
        }
        .footer-column a:hover {
            color: var(--white);
        }
        .copyright {
            text-align: center;
            margin-top: 40px;
            padding-top: 20px;
            border-top: 1px solid #444;
            font-size: 14px;
        }
        /* Responsive */
